htmlTemplate.css:
:root {
  --navy: #002f6d;
  --band-gray-bg: #d1d5db;
  --band-gray-text: #111827;
  --body-text: #111827;
  --muted: #9CA3AF;
  --alt-row: #F4F6FA;
  --gold: #e0a800;
}
* { box-sizing: border-box; }
body { font-family: Helvetica, Arial, sans-serif; font-size: 8pt; color: var(--body-text); }
.header { display: flex; flex-direction: row; justify-content: space-between; align-items: flex-start; }
.header-center { flex: 1; text-align: center; }
.project-title { font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold; font-size: 13pt; }
.header-sub { font-size: 8pt; color: #374151; margin-top: 2pt; }
.header-right { text-align: right; width: 170pt; }
.header-right-bold { font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold; font-size: 10pt; }
.header-right-sm { font-size: 7.5pt; color: #374151; margin-top: 1pt; }
.rule { border-bottom: 1.5pt solid var(--navy); margin: 4pt 0 6pt; }
.cols { display: flex; flex-direction: row; gap: 10pt; }
.left-col { width: 280pt; }
.right-col { flex: 1; }
.box { border: 0.5pt solid var(--muted); margin-bottom: 6pt; }
.band { background: var(--navy); color: #fff; font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold; font-size: 9pt; padding: 3pt 6pt; display: flex; flex-direction: row; justify-content: space-between; }
.kv { display: flex; flex-direction: row; justify-content: space-between; padding: 2.5pt 6pt; border-bottom: 0.5pt solid #e5e7eb; font-size: 8.5pt; }
.kv:last-child { border-bottom: none; }
.kv-value { font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold; }
.std-table { width: 100%; border-collapse: collapse; font-size: 8.5pt; }
.std-table th { background: #eef2f8; font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold; padding: 3pt 5pt; text-align: left; }
.std-table th.r, .std-table td.r { text-align: right; }
.std-table td { padding: 2.5pt 5pt; border-bottom: 0.5pt solid #e5e7eb; }
.std-table tr.total td { background: #f3f4f6; font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold; border-top: 0.5pt solid var(--muted); }
.section-band { background: var(--navy); color: #fff; font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold; font-size: 10pt; padding: 3pt 8pt; margin-top: 8pt; margin-bottom: 3pt; }
.chart-caption { font-size: 7pt; color: #6b7280; text-align: center; margin-top: 2pt; }
.foot-note { font-size: 7pt; color: var(--muted); margin-top: 8pt; }
.empty-note { font-size: 8.5pt; color: var(--muted); font-style: italic; padding: 5pt; }
.delay-columns { display: flex; flex-direction: row; gap: 10pt; }
.delay-col { flex: 1; }
